(() => {
 'use strict';
 // Independent mechanics illustrations, not Nastran solution results or input decks.
 const ui=window.BeamLabs.ui,G=window.BeamLabs.graphics,A=window.LessonArticle;
 const fmt=(x,n=4)=>Number.isFinite(x)?Number((Math.abs(x)<1e-10?0:x).toPrecision(n)).toLocaleString('en-US',{maximumFractionDigits:6}):'—';
 const core={
  vector:(angle,scale,unit=false)=>{const a=angle*Math.PI/180,n=unit?1:scale;return {x:100*n*Math.cos(a),y:100*n*Math.sin(a),mag:100*n};},
  eccentric:(x,y,angle)=>{const a=angle*Math.PI/180,Fx=100*Math.cos(a),Fy=100*Math.sin(a);return {Fx,Fy,M:x*Fy-y*Fx};},
  line:(qa,qb,L=400)=>{const F=L*(qa+qb)/2,M=L*L*(qa+2*qb)/6;return {F,M,x:Math.abs(F)>1e-10?M/F:null,RA:F-M/L,RB:M/L};},
  projection:(angle,q=.5,L=400)=>{const c=Math.cos(angle*Math.PI/180);return {length:L,projected:L*c,actual:q*L,project:q*L*c};},
  pressure:(kind,sign,angle)=>{const a=angle*Math.PI/180,n=[Math.sin(a),0,Math.cos(a)],s=sign*(kind==='solid'?-1:1);return {n,F:n.map(x=>600*s*x)};},
  edge:(quadratic,q=1,L=300)=>({f:quadratic?[q*L/6,2*q*L/3,q*L/6]:[q*L/2,q*L/2],x:quadratic?[0,L/2,L]:[0,L]}),
  beam:(consistent,q=.5,L=400,EI=210000*10000)=>{const F=q*L/2,M=consistent?-q*L*L/12:0;return {F,M,u:F*L**3/(3*EI)+M*L*L/(2*EI),theta:F*L*L/(2*EI)+M*L/EI,exact:q*L**4/(8*EI),f:[q*L/2,consistent?q*L*L/12:0,F,M]};},
  mass:kind=>{const V=1e6,g=9810,rho=kind==='kg'?7.85e-6:kind==='weight'?7.85e-9*g:7.85e-9,w=kind==='weight'?1/g:1,m=rho*V*w;return {rho,w,m,kg:m*1000,F:m*g};},
  rotation:(rpm,r=.2,m=2)=>{const A=rpm/60,omega=2*Math.PI*A;return {A,omega,F:m*omega*omega*r};},
  combination:(a,b,S=1)=>{const sx=S*100*a,sy=S*100*b;return {sx,sy,vm:Math.sqrt(sx*sx-sx*sy+sy*sy),wrong:100*S*(a+b)};}
 };
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const text=(x,y,s,a='middle')=>`<text x="${x}" y="${y}" text-anchor="${a}">${esc(s)}</text>`;
 const line=(a,b,c='el-edge')=>`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" class="${c}"/>`;
 const poly=(ps,c='el-edge')=>`<polyline points="${ps.map(p=>p.join(',')).join(' ')}" class="${c}"/>`;
 const node=(x,y)=>`<circle cx="${x}" cy="${y}" r="4" class="el-node"/>`;
 function arrow(a,b,c='el-force'){const dx=b[0]-a[0],dy=b[1]-a[1],l=Math.hypot(dx,dy);if(l<.01)return '';const u=dx/l,v=dy/l,h=Math.min(8,l/2);return line(a,b,c)+`<polygon points="${b} ${b[0]-h*u+3*v},${b[1]-h*v-3*u} ${b[0]-h*u-3*v},${b[1]-h*v+3*u}" class="${c}-head"/>`;}
 const svg=(body,label,h=250)=>`<svg class="theory-lab-svg" viewBox="0 0 360 ${h}" role="img" aria-label="${esc(label)}">${body}</svg>`;
 const wall=(x,y)=>line([x,y-25],[x,y+25])+[-2,-1,0,1,2].map(i=>line([x,y+i*10],[x-9,y+i*10+8])).join('');
 const support=(x,y)=>`<path d="M${x} ${y}l-10 16h20Z" class="el-soft"/>`+line([x-15,y+20],[x+15,y+20]);
 const frame=(c,caption)=>ui.box('',c,caption),table=(h,r)=>A.table(h,r,{narrow:true});
 const out=(e,v)=>Object.entries(v).forEach(([k,x])=>{if(e.out[k])e.out[k].textContent=fmt(+x);});
 const labs={
  vector:{html:()=>frame(ui.slider('angle','荷重ベクトルの角度（°）',0,90,5,30)+ui.slider('scale','入力ベクトルの長さ',.5,2,.25,2)+ui.select('kind','大きさの定義',[['force','FORCE：F × N'],['unit','FORCE1：F × 単位方向']],'force'),'係数F=100 N。赤の実線が実際の力、灰色の破線が長さ1の方向を使った100 Nの基準（見分けるため少し平行移動）。FORCE1の方向は2節点から決めます。'),draw(e,v){out(e,v);const r=core.vector(+v.angle,+v.scale,v.kind==='unit'),a=+v.angle*Math.PI/180,o=[55,210],end=[o[0]+r.x,o[1]-r.y];e.plot.innerHTML=svg(arrow(o,[305,210],'el-axis')+arrow(o,[55,25],'el-axis')+text(320,214,'x')+text(42,24,'y')+line([55,224],[55+100*Math.cos(a),224-100*Math.sin(a)],'el-ghost')+text(68+100*Math.cos(a),239-100*Math.sin(a),'100 N','start')+arrow(o,end)+node(...o)+text(55,236,'G'),'方向とベクトルの長さで実際の力が変わる',270)+table(['Fx (N)','Fy (N)','|f| (N)'],[[fmt(r.x),fmt(r.y),fmt(r.mag)]]);e.readout.innerHTML=v.kind==='force'?'<strong>FORCEのNは自動で長さ1になりません。</strong>方向が正しくても、長さを2にすると力も200 Nになります。':'<strong>FORCE1ではG1→G2を単位方向にして使います。</strong>2点間の距離を変えても向きが同じなら大きさは100 Nのままです。';}},
  eccentric:{html:()=>frame(ui.slider('x','作用点のx（mm）',0,100,10,80)+ui.slider('y','作用点のy（mm）',-60,60,10,40)+ui.slider('angle','力の角度（°）',-90,90,15,0),'Oからの位置rに100 Nを加える2次元の例。赤は力、灰色の破線は位置ベクトル。Oへ移すなら同じ力に加えてMzが必要です。'),draw(e,v){out(e,v);const r=core.eccentric(+v.x,+v.y,+v.angle),o=[95,130],p=[95+Number(v.x),130-Number(v.y)],end=[p[0]+.5*r.Fx,p[1]-.5*r.Fy];e.plot.innerHTML=svg(arrow([35,218],[100,218],'el-axis')+arrow([35,218],[35,170],'el-axis')+text(113,222,'x')+text(24,165,'y')+line(o,p,'el-ghost')+node(...o)+node(...p)+arrow(p,end)+text(80,132,'O')+text(p[0]-12,p[1]+22,'P')+text(215,225,'Mz = xFy − yFx'),'偏心した力と基準点まわりのモーメント')+table(['Fx (N)','Fy (N)','Mz (N·mm)'],[[fmt(r.Fx),fmt(r.Fy),fmt(r.M)]]);e.readout.innerHTML='<strong>力の移動では、力の大きさだけを保存しません。</strong>同じ作用線上ならr×Fは変わりませんが、作用線を平行移動するとモーメントが変わります。反時計回りをMzの正としています。';}},
  line:{html:()=>frame(ui.slider('qa','左端の下向き線荷重 qa（N/mm）',0,2,.25,.5)+ui.slider('qb','右端の下向き線荷重 qb（N/mm）',0,2,.25,1.5),'L=400 mmの単純支持梁。赤の矢印は線荷重、緑の破線矢印は反力。数値は積分による静力学の計算で、有限要素解析結果ではありません。'),draw(e,v){out(e,v);const r=core.line(+v.qa,+v.qb),ps=Array.from({length:9},(_,i)=>{const t=i/8,q=+v.qa+(v.qb-v.qa)*t;return [55+250*t,125-35*q];});e.plot.innerHTML=svg(line([55,135],[305,135])+support(55,135)+support(305,135)+poly(ps,'el-force')+ps.map(([x,y])=>arrow([x,y],[x,125])).join('')+text(55,35,'qa')+text(305,35,'qb')+(r.x===null?'':line([55+250*r.x/400,139],[55+250*r.x/400,172],'el-ghost')+node(55+250*r.x/400,135)+text(55+250*r.x/400,190,'x̄'))+arrow([55,215],[55,215-r.RA*.18],'el-motion')+arrow([305,215],[305,215-r.RB*.18],'el-motion')+text(55,237,'RA')+text(305,237,'RB'),'台形分布の合力、作用点、左右の反力')+table(['合力 F (N)','作用点 x̄ (mm)','RA / RB (N)'],[[fmt(r.F),r.x===null?'—':fmt(r.x),fmt(r.RA)+' / '+fmt(r.RB)]]);e.readout.innerHTML=r.F===0?'荷重が0なら反力も0です。合力0のため、この例の作用点x̄は定義しません。':'<strong>合力は分布の面積、作用点はその重心です。</strong>qa=0なら三角形の重心は左から2L/3に寄ります。同じ合力でも、その位置によって反力分担が変わります。';}},
  projection:{html:()=>frame(ui.slider('angle','水平面からの梁の角度（°）',0,75,5,45)+ui.select('basis','線荷重の基準',[['actual','実長：LE / FR'],['project','水平投影長：LEPR / FRPR']],'actual'),'梁の実長400 mm、鉛直下向き0.5 N/mm。投影長の比較は全体y方向荷重に対する2次元の例です。FRでも荷重強さが無次元になるわけではありません。'),draw(e,v){out(e,v);const r=core.projection(+v.angle),a=v.angle*Math.PI/180,A0=[55,235],B=[55+200*Math.cos(a),235-200*Math.sin(a)],ps=Array.from({length:7},(_,i)=>[A0[0]+(B[0]-A0[0])*i/6,A0[1]+(B[1]-A0[1])*i/6]);e.plot.innerHTML=svg(line(A0,B)+line(A0,[B[0],235],'el-ghost')+line(B,[B[0],235],'el-ghost')+ps.map(([x,y])=>arrow([x,y-35],[x,y-5])).join('')+node(...A0)+node(...B)+text(42,251,'A')+text(B[0]+15,B[1]+5,'B')+text(180,280,'L = 400 mm'),'同じ強さでも実長と投影長で合力が変わる',300)+table(['実長 (mm)','投影長 (mm)','選択した合力 (N)'],[[400,fmt(r.projected),fmt(v.basis==='actual'?r.actual:r.project)]]);e.readout.innerHTML='<strong>入力する位置X1・X2は、投影方式でも梁の軸に沿った距離または割合です。</strong>荷重を「屋根の実面積」で与えたのか「水平投影」で与えたのかを先に確認します。';}},
  pressure:{html:()=>frame(ui.select('kind','同じ上側の面を選ぶ',[['shell','シェル：正の要素法線'],['solid','ソリッド：外向き法線の逆']],'shell')+ui.select('sign','PLOAD4の面圧',[['1','+2 N/mm²'],['-1','−2 N/mm²']],'1')+ui.slider('angle','面の傾き（°）',0,60,15,15),'面積300 mm²。継続行で方向を指定しないPLOAD4の符号比較。青がシェルの正法線／ソリッドの外向き法線n、赤が荷重。形状は独自の模式図、矢印長は模式的です。'),draw(e,v){out(e,v);const r=core.pressure(v.kind,+v.sign,+v.angle),a=v.angle*Math.PI/180,rot=([x,y,z])=>[x*Math.cos(a)+z*Math.sin(a),y,-x*Math.sin(a)+z*Math.cos(a)],face=[[-1,-.7,0],[1,-.7,0],[1,.7,0],[-1,.7,0]],items=[];if(v.kind==='solid'){for(let i=0;i<4;i++)items.push({k:'face',p:[face[i],face[(i+1)%4],face[(i+1)%4].map((x,j)=>j===2?-.45:x),face[i].map((x,j)=>j===2?-.45:x)].map(rot),n:rot([[0,-1,0],[1,0,0],[0,1,0],[-1,0,0]][i]),two:true,rgb:[160,185,207],op:.7});}items.push({k:'face',p:face.map(rot),n:r.n,two:true,rgb:[184,204,223],op:.8},{k:'poly',p:[...face,face[0]].map(rot),c:'b3-edge'},{k:'arrow',p:[rot([-.9,.6,0]),rot([-.9,.6,.9])],c:'b3-axis'},{k:'text',p:[rot([-.9,.6,1.05])],s:'n'});const axisO=[-1.35,-.9,-.55];for(let j=0;j<3;j++){const tip=axisO.map((x,k)=>x+(j===k?.4:0));items.push({k:'arrow',p:[axisO,tip],c:'b3-axis'},{k:'text',p:[tip],s:['x','y','z'][j],dx:4,dy:-4});}const s=+v.sign*(v.kind==='solid'?-1:1);for(const x of [-.55,0,.55]){const p=rot([x,0,0]);items.push({k:'arrow',p:[p,rot([x,0,s*.8])],c:'b3-load'});}e.plot.innerHTML=G.render3d(items,{w:360,h:260,pad:30,cam:G.camera(30,25),label:'シェルとソリッドの正圧力、面の法線nと荷重方向'})+table(['Fx (N)','Fy (N)','Fz (N)'],[[...r.F.map(x=>fmt(x))]]);e.readout.innerHTML='<strong>正の面圧が同じ向きとは限りません。</strong>シェルは節点順から決まる正法線、ソリッドは選択した面の内側へ作用します。面番号・節点順・符号を、荷重矢印と反力で照合します。';}},
  consistent:{html:()=>frame(ui.select('kind','直線辺の補間',[['linear','2節点の線形補間'],['quadratic','3節点の2次補間']],'quadratic')+ui.select('method','節点力の決め方',[['work','仮想仕事を一致させる'],['equal','節点数で均等割り（比較用）']],'work'),'長さ300 mm、下向き1 N/mm。赤は等価節点力。緑の破線は検算用の仮想変位（拡大表示）です。仮想変位は2節点では両端1 mm、3節点では両端0・中間1 mmを使い、同じ変位場で分布荷重の仕事と比較します。'),draw(e,v){const quad=v.kind==='quadratic',r=core.edge(quad),f=v.method==='equal'?r.f.map(()=>300/r.f.length):r.f,works=quad?200:300,workn=quad?f[1]:f.reduce((s,x)=>s+x,0),ps=r.x.map(x=>55+250*x/300);e.plot.innerHTML=svg(line([55,145],[305,145])+poly(Array.from({length:31},(_,i)=>{const t=i/30;return[55+250*t,145+50*(quad?4*t*(1-t):1)];}),'el-motion')+ps.map((x,i)=>arrow([x,135-.45*f[i]],[x,135])+node(x,145)+text(x,168,String(i+1))).join('')+text(180,25,'q = 1 N/mm')+text(180,215,'L = 300 mm'),'同じ合力でも分布荷重の仕事を再現できるか')+table(['節点','力 (N)'],f.map((x,i)=>[i+1,fmt(x)]))+table(['分布荷重の仕事 (N·mm)','節点力の仕事 (N·mm)'],[[works,fmt(workn)]]);e.readout.innerHTML=quad&&v.method==='equal'?'<strong>合力300 Nは合っても、仕事は半分です。</strong>中間点が動く変形を正しく加力できず、変位・応力に差が出ます。':'<strong>等価とは、許された変位場に対する仕事が同じことです。</strong>2次辺では中間点がより広い範囲の変位を表すため、1 : 4 : 1になります。';}},
  beam:{html:()=>frame(ui.select('method','一つの梁要素に置く等価荷重',[['consistent','節点力と節点モーメント'],['force','節点力だけ（比較用）']],'consistent'),'片持ち梁L=400 mm、EI=2.1×10⁹ N·mm²、下向きq=0.5 N/mm。実線は一つのEuler–Bernoulli梁要素の補間、破線は変形前。変形は100倍で表示。符号は下向き変位とそのx微分の回転を正とする局所的な計算規約です。'),draw(e,v){const r=core.beam(v.method==='consistent'),L=400,ps=Array.from({length:31},(_,i)=>{const t=i/30,w=(3*t*t-2*t**3)*r.u+L*(-t*t+t**3)*r.theta;return[50+250*t,90+100*w];});e.plot.innerHTML=svg(wall(50,90)+line([50,90],[300,90],'el-ghost')+poly(ps,'b3-edge')+Array.from({length:8},(_,i)=>arrow([50+i*250/7,35],[50+i*250/7,72])).join('')+text(180,22,'q')+text(180,238,'×100'),'節点モーメントを省略すると梁の変位が変わる')+table(['等価荷重','A','B'],[['力 (N)',fmt(r.f[0]),fmt(r.f[2])],['モーメント (N·mm)',fmt(r.f[1]),fmt(r.f[3])]])+table(['先端変位 (mm)','厳密値との比'],[[fmt(r.u),fmt(r.u/r.exact)]]);e.readout.innerHTML=v.method==='consistent'?'<strong>先端変位は連続梁のqL⁴/(8EI)と一致します。</strong>ただし要素内の変位は3次補間なので、等分布荷重の厳密な4次変位曲線とは全域で一致しません。':'<strong>同じ合力・モーメントでも先端変位は4/3倍。</strong>端部モーメントの組は合計0でも、節点回転に対する仕事を受け持ちます。合力だけを合わせた置換では失われます。';}},
  mass:{html:()=>frame(ui.select('kind','N・mm・sのモデルに入れる密度',[['mass','質量密度（tonne/mm³）'],['weight','重量密度（WTMASS=1/g）'],['kg','kg/mm³を変換せず入力']],'mass'),'体積10⁶ mm³、g=9810 mm/s²。N・mm・sでは質量単位はtonneです。物体の形を変えずに単位の整合だけを比較しています。'),draw(e,v){const r=core.mass(v.kind);e.plot.innerHTML=svg(`<rect x="105" y="60" width="150" height="85" class="el-fill"/>${text(180,95,'V = 10⁶ mm³')}${text(180,122,'ρ')}${arrow([180,150],[180,208])}${text(226,191,'mg')}${arrow([70,75],[70,135],'el-axis')}${text(70,57,'g')}`,'質量密度、重力加速度、重量の関係')+table(['質量 (tonne)','kgへ換算','重量 (N)'],[[fmt(r.m),fmt(r.kg),fmt(r.F)]])+table(['密度の入力値','WTMASS'],[[r.rho.toExponential(5),r.w.toExponential(5)]]);e.readout.innerHTML=v.kind==='kg'?'<strong>質量も重量も1000倍になっています。</strong>入力値に単位名は付かないため、数値を一貫した単位へ変換します。WTMASSを場当たり的に変える前に、材料・集中質量・非構造質量を同じ基準へそろえます。':'この設定の質量は<strong>7.85 kg</strong>、重量は<strong>77.0085 N</strong>です。質量密度で入力した上に1/gを再度掛けると、二重変換になります。';}},
  rotation:{html:()=>frame(ui.slider('rpm','回転数（rpm）',0,1800,100,600)+ui.slider('radius','回転軸からの半径（m）',.1,.4,.05,.2),'質点2 kg、単位はN・m・s。赤は回転系での外向き遠心荷重。一定回転の例で、角加速度・ジャイロ効果・質量オフセットは含めません。矢印長は模式的です。'),draw(e,v){out(e,v);const r=core.rotation(+v.rpm,+v.radius),x=130+200*v.radius;e.plot.innerHTML=svg(`<circle cx="130" cy="130" r="${200*v.radius}" class="el-ghost"/>${node(130,130)}${line([130,130],[x,130])}${node(x,130)}${v.rpm>0?arrow([x,130],[x+65,130]):''}${text(115,149,'O')}${text(x,111,'m')}${text((130+x)/2,151,'r')}${text(180,26,'F = mω²r')}`,'回転数の2乗で増える遠心荷重',280)+table(['A (rev/s)','ω (rad/s)','遠心荷重 (N)'],[[fmt(r.A),fmt(r.omega),fmt(r.F)]]);e.readout.innerHTML='<strong>回転数2倍では荷重4倍です。</strong>rpmをRFORCEのAへそのまま入れると回転数が60倍、遠心荷重が3600倍になります。この例では方向ベクトルRを長さ1にしています。';}},
  combination:{html:()=>frame(ui.slider('a','ケースAの係数 a',-2,2,.25,1)+ui.slider('b','ケースBの係数 b',-2,2,.25,1),'同じ位置・同じ座標での平面応力。ケースA：σx=100 MPa、ケースB：σy=100 MPa、どちらもτxy=0。成分を重ねてからミーゼス応力を計算します。'),draw(e,v){out(e,v);const r=core.combination(+v.a,+v.b),o=[180,125],sx=.4*r.sx,sy=.4*r.sy;let body='<rect x="145" y="90" width="70" height="70" class="el-fill"/>';for(const sign of [-1,1]){const p=[o[0]+sign*42,o[1]];body+=arrow(p,[p[0]+sign*sx,p[1]]);const q=[o[0],o[1]-sign*42];body+=arrow(q,[q[0],q[1]-sign*sy]);}e.plot.innerHTML=svg(body+text(285,146,'σx')+text(209,35,'σy')+text(180,244,'τxy = 0'),'応力成分を先に重ね合わせる',265)+table(['σx (MPa)','σy (MPa)','正しいσVM (MPa)'],[[fmt(r.sx),fmt(r.sy),fmt(r.vm)]])+table(['ミーゼス値を直接足した場合 (MPa)'],[[fmt(r.wrong)]]);e.readout.innerHTML='<strong>最大値・主応力・ミーゼス値は、そのまま加算しません。</strong>a=b=1なら正しい値は100 MPa、個別のミーゼス値の和は200 MPaです。負係数では誤った和が負になる場合すらあります。';}}
 };
 function connect(root){for(const e of root.querySelectorAll('[data-load-lab]'))ui.mount(e,labs[e.dataset.loadLab]);}
 window.LoadLabs={core,labs,connect};
})();
